/* @autogenerated */
package net.civeira.phylax.feature.oauth.gdpr.infrastructure.driven;

import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mockito;

import net.civeira.phylax.common.infrastructure.mail.EmailMessage;
import net.civeira.phylax.common.infrastructure.mail.EmailService;
import net.civeira.phylax.feature.oauth.consent.infrastructure.driven.ScopesConsentAdapter;
import net.civeira.phylax.feature.oauth.user.infrastructure.VerificationCodeService;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The right to erasure (GDPR art. 17) applied on the h2 database. */
class AccountDeletionAdapterUnitTest {
  private OidcRepositories store;
  private EmailService mail;
  private AccountDeletionAdapter deletion;
  private String tenant;
  private String alice;
  private String bob;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    tenant = store.tenant("acme");
    alice = store.user(tenant, "alice", "alice@acme.test");
    bob = store.user(tenant, "bob", "bob@acme.test");
    store.client(tenant, "web", "Web portal");
    mail = Mockito.mock(EmailService.class);
    deletion = new AccountDeletionAdapter(store.userWriter(),
        new VerificationCodeService(store.verificationCodes(), store.digester()),
        store.consentWriter(), store.dataSource(), mail);
    ScopesConsentAdapter consents = new ScopesConsentAdapter(store.users(), store.tenants(),
        store.clients(), store.consents(), store.consentWriter());
    for (String[] user : new String[][] {{"alice", alice}, {"bob", bob}}) {
      consents.storeAcceptedScopes("acme", user[0], "web", List.of("openid", "email"));
      store.db()
          .execute("INSERT INTO _oauth_session (session, user_uid, client_id, issuer,"
              + " auth_data, csid) VALUES ('s-" + user[0] + "', '" + user[1]
              + "', 'web', 'iss', '{\"uid\":\"" + user[1] + "\"}', 'c')");
      store.db()
          .execute("INSERT INTO _oauth_audit_log (uid, tenant_id, event_type, user_id,"
              + " created_at) VALUES ('" + OidcRepositories.uid() + "', '" + tenant
              + "', 'login', '" + user[1] + "', CURRENT_TIMESTAMP)");
    }
  }

  /** Request the deletion and return the code of the confirmation link sent by mail. */
  private String request() {
    deletion.requestDeletion(alice, "alice", "alice@acme.test", "acme", "https://acme.test/delete");
    ArgumentCaptor<EmailMessage> sent = ArgumentCaptor.forClass(EmailMessage.class);
    Mockito.verify(mail).delaySendMessage(sent.capture());
    Assertions.assertEquals("alice@acme.test", sent.getValue().getTargetAddress());
    Matcher link = Pattern.compile("https://acme.test/delete\\?uid=" + alice + "&code=([0-9a-f-]+)")
        .matcher(sent.getValue().getContent());
    Assertions.assertTrue(link.find(), "The mail carries the confirmation link");
    return link.group(1);
  }

  private String column(String sql) {
    return store.value(sql);
  }

  @Test
  @DisplayName("The confirmed deletion anonymizes the user and erases its sessions, consents and audit")
  void confirm() {
    String code = request();
    Assertions.assertNotEquals(code,
        column(
            "SELECT code_hash FROM access_user_verification_code WHERE `user` = '" + alice + "'"),
        "The code is stored as a digest");

    Assertions.assertTrue(deletion.confirmDeletion(alice, code, "acme"));

    Assertions.assertEquals("Deleted User",
        column("SELECT name FROM identity_user WHERE uid = '" + alice + "'"));
    Assertions.assertEquals("deleted-" + alice + "@deleted.invalid",
        column("SELECT email FROM identity_user WHERE uid = '" + alice + "'"));
    Assertions.assertEquals("FALSE",
        column("SELECT enabled FROM identity_user WHERE uid = '" + alice + "'").toUpperCase());
    Assertions
        .assertNotNull(column("SELECT revoked_at FROM _oauth_session WHERE session = 's-alice'"));
    Assertions.assertEquals(0,
        store.db().count("access_user_scope_consent", "`user` = '" + alice + "'"));
    Assertions.assertEquals(0, store.db().count("_oauth_audit_log", "user_id = '" + alice + "'"));
    Assertions.assertEquals(2, store.db().count("_oauth_audit_log", null),
        "The audit entries stay, without the user");

    Assertions.assertEquals("bob",
        column("SELECT name FROM identity_user WHERE uid = '" + bob + "'"));
    Assertions.assertNull(column("SELECT revoked_at FROM _oauth_session WHERE session = 's-bob'"));
    Assertions.assertEquals(2,
        store.db().count("access_user_scope_consent", "`user` = '" + bob + "'"));

    Assertions.assertFalse(deletion.confirmDeletion(alice, code, "acme"),
        "A confirmation code is used only once");
  }

  @Test
  @DisplayName("A wrong or missing code deletes nothing")
  void wrong_code() {
    request();

    Assertions.assertFalse(deletion.confirmDeletion(alice, "not-the-code", "acme"));
    Assertions.assertFalse(deletion.confirmDeletion(alice, "", "acme"));
    Assertions.assertFalse(deletion.confirmDeletion(bob, "any", "acme"), "Bob asked for nothing");

    Assertions.assertEquals("alice",
        column("SELECT name FROM identity_user WHERE uid = '" + alice + "'"));
    Assertions.assertEquals(4, store.db().count("access_user_scope_consent", null));
  }

  @Test
  @DisplayName("The html of the mail escapes the tenant and the link")
  void escaped_mail() {
    deletion.requestDeletion(alice, "alice", "alice@acme.test", "<acme>",
        "https://acme.test/delete");

    ArgumentCaptor<EmailMessage> sent = ArgumentCaptor.forClass(EmailMessage.class);
    Mockito.verify(mail).delaySendMessage(sent.capture());
    String html = sent.getValue().getHtmlContent();
    Assertions.assertTrue(html.contains("&lt;acme&gt;"), "The tenant is escaped on the html");
    Assertions.assertTrue(html.contains("&amp;code="), "The link is escaped on the html");
  }

  @Test
  @DisplayName("A failure on the mail does not break the request, the code is still issued")
  void request_mail_failure() {
    Mockito.doThrow(new IllegalStateException("smtp down")).when(mail)
        .delaySendMessage(Mockito.any());

    Assertions.assertDoesNotThrow(() -> deletion.requestDeletion(alice, "alice", "alice@acme.test",
        "acme", "https://acme.test/delete"));
    Assertions.assertEquals(1,
        store.db().count("access_user_verification_code", "`user` = '" + alice + "'"));
  }

  @Test
  @DisplayName("The traces are erased even if the user is already gone")
  void confirm_without_user() {
    String code = request();
    store.db().execute("SET REFERENTIAL_INTEGRITY FALSE");
    store.db().execute("DELETE FROM identity_user WHERE uid = '" + alice + "'");

    Assertions.assertTrue(deletion.confirmDeletion(alice, code, "acme"));

    Assertions
        .assertNotNull(column("SELECT revoked_at FROM _oauth_session WHERE session = 's-alice'"));
    Assertions.assertEquals(0,
        store.db().count("access_user_scope_consent", "`user` = '" + alice + "'"));
    Assertions.assertEquals(0, store.db().count("_oauth_audit_log", "user_id = '" + alice + "'"));
  }
}
